import { Order } from '../../domain/entities/Order';
import type { OrderRepository } from '../../domain/repositories/OrderRepository';
import type { ProductRepository } from '../../domain/repositories/ProductRepository';
import type { StockAllocator } from '../../domain/services/StockAllocationService';
import type { Clock } from '../ports/Clock';
import type { IdGenerator } from '../ports/IdGenerator';
import { productIn, requireProducts } from './lookups';
import type { OrderDto, PlaceOrderCommand } from './OrderDtos';
import { toOrderDto } from './OrderMapper';

export interface PlaceOrder {
  execute(command: PlaceOrderCommand): OrderDto;
}

/** Places an order at current catalogue prices and reserves its stock. */
export class PlaceOrderUseCase implements PlaceOrder {
  constructor(
    private readonly orders: OrderRepository,
    private readonly products: ProductRepository,
    private readonly stock: StockAllocator,
    private readonly ids: IdGenerator,
    private readonly clock: Clock,
  ) {}

  execute(command: PlaceOrderCommand): OrderDto {
    const products = requireProducts(
      this.products,
      command.items.map((item) => item.productId),
    );
    const order = Order.place({
      id: this.ids.next(),
      customerId: command.customerId,
      lines: command.items.map((item) => ({
        productId: item.productId,
        quantity: item.quantity,
        unitPriceCents: productIn(products, item.productId).priceCents,
      })),
      at: this.clock.now(),
    });

    this.stock.reserve(order.lines, products);

    products.forEach((product) => this.products.save(product));
    this.orders.save(order);
    return toOrderDto(order);
  }
}

